"A TV ainda está gerando o certificado. Volte em 1 minuto.":"ทีวียังสร้างใบรับรองอยู่ กลับมาใหม่ใน 1 นาที",
"A TV ainda não deu acesso às sessões de mídia (o shell do launcher precisa estar de pé).":"ทีวียังเข้าถึงเซสชันสื่อไม่ได้ (เชลล์ของ Launcher ต้องทำงานอยู่)",
"A TV avisa no celular: lembrete de jogo, alarme perdido, TV ligada de madrugada, erro, pedido de ajuda. Funciona com o painel aberto pelo endereço https (Tailscale, porta 8443) e o Chrome do Android. O aviso sai cifrado da TV.":"ทีวีแจ้งเตือนไปที่โทรศัพท์ของคุณ: เตือนเกม นาฬิกาปลุกที่พลาด ทีวีเปิดดึก ข้อผิดพลาด ขอความช่วยเหลือ ใช้ได้เมื่อเปิดแผงควบคุมด้วยที่อยู่ https (Tailscale พอร์ต 8443) ใน Chrome บน Android การแจ้งเตือนออกจากทีวีแบบเข้ารหัส",
"A TV desliga e liga de novo (cerca de 1 min). O painel volta sozinho depois.":"ทีวีจะปิดและเปิดใหม่ (ประมาณ 1 นาที) แผงควบคุมจะกลับมาเอง",
"A TV entra na sua rede Tailscale e publica só o MCP na internet.":"ทีวีจะเข้าร่วมเครือข่าย Tailscale ของคุณและเผยแพร่เฉพาะ MCP บนอินเทอร์เน็ต",
"A TV está sem conta Google (ou o launcher está sem a permissão de ver as contas).":"ทีวีไม่มีบัญชี Google (หรือ Launcher มองไม่เห็นบัญชี)",
"A TV fala direto com o Home Assistant da casa (sem nuvem): luzes e cenas aqui, na TV (Extras > Casa) e pelo Claude. Ela também aparece lá como sensor (ligada/dormindo, app aberto). O token fica cifrado na TV. Configurar pede o PIN.":"ทีวีคุยกับ Home Assistant ของคุณโดยตรง (ไม่ผ่านคลาวด์): ไฟและฉากที่นี่ บนทีวี (Extras > บ้าน) และผ่าน Claude ทีวียังแสดงที่นั่นเป็นเซนเซอร์ (เปิด/พักเครื่อง แอปที่เปิดอยู่) โทเค็นเก็บแบบเข้ารหัสบนทีวี การตั้งค่าต้องใช้ PIN",
"A TV guarda sozinha uma cópia por dia (as últimas 7), só quando algo mudou. Baixe uma para restaurar em outra TV, ou volte esta TV para o estado daquele dia.":"ทีวีเก็บสำเนาวันละหนึ่งชุดเอง (7 ชุดล่าสุด) เฉพาะเมื่อมีการเปลี่ยนแปลง ดาวน์โหลดไปกู้คืนบนทีวีอีกเครื่อง หรือย้อนทีวีเครื่องนี้กลับไปวันนั้น",
"A TV ligou":"ทีวีเปิดแล้ว",
"A TV manda cada linha nova das origens marcadas (POST com JSON) para este endereço: https, ou http só dentro de casa (ex.: um webhook do Home Assistant). Mudar pede o PIN. Vazio desliga.":"ทีวีจะส่งทุกบรรทัดใหม่จากแหล่งที่เลือก (POST พร้อม JSON) ไปยังที่อยู่นี้: https หรือ http เฉพาะในบ้าน (เช่น webhook ของ Home Assistant) การเปลี่ยนต้องใช้ PIN เว้นว่างเพื่อปิด",
"A TV não criou a chave dos avisos. Tente de novo.":"ทีวีสร้างคีย์การแจ้งเตือนไม่ได้ ลองอีกครั้ง",
