"A TV passa a responder pela internet (Tailscale Funnel). Quem entrar precisa do PIN.":"ทีวีจะเริ่มตอบผ่านอินเทอร์เน็ต (Tailscale Funnel) ผู้ที่ลงชื่อเข้าใช้ต้องมี PIN",
"A TV sai da rede Tailscale. Para voltar, cole uma chave nova.":"ทีวีจะออกจากเครือข่าย Tailscale หากจะกลับมา ให้วางคีย์ใหม่",
