"Cada \"aparelho:porta\" vira http://127.0.0.1:porta na TV: no Jellyfin, Emby ou Kodi, use esse endereço como servidor. Só com a rede Tailscale ligada. Na mesma rede de casa não precisa.":"แต่ละ \"อุปกรณ์:พอร์ต\" จะกลายเป็น http://127.0.0.1:พอร์ต บนทีวี: ใน Jellyfin, Emby หรือ Kodi ใช้ที่อยู่นั้นเป็นเซิร์ฟเวอร์ ใช้ได้เมื่อเปิดเครือข่าย Tailscale เท่านั้น ไม่จำเป็นเมื่ออยู่ในเครือข่ายบ้านเดียวกัน",
"Cada evento roda no máximo uma vez a cada 20 s. Filmes de outros apps precisam do acesso às notificações (\"Tocando agora\").":"แต่ละเหตุการณ์ทำงานได้มากสุดหนึ่งครั้งทุก 20 วินาที ภาพยนตร์จากแอปอื่นต้องมีสิทธิ์เข้าถึงการแจ้งเตือน (\"กำลังเล่น\")",
