"Cima":"ขึ้น",
"Claude (claude.ai, app do celular ou do PC)":"Claude (claude.ai แอปบนโทรศัพท์หรือคอมพิวเตอร์)",
"Claude pela internet (MCP)":"Claude ผ่านอินเทอร์เน็ต (MCP)",
"Claude, ChatGPT e outras IAs controlam a TV: controle remoto, abrir apps e links, instalar APK, despertadores, avisos, arquivos e shell. O que pede OK no controle segue as Confirmações. O login é este mesmo PIN, ou a conta Google, se ligada abaixo. O painel não fica na internet: só o MCP.":"Claude, ChatGPT และ AI อื่นๆ ควบคุมทีวีได้: รีโมต เปิดแอปและลิงก์ ติดตั้ง APK นาฬิกาปลุก ข้อความ ไฟล์ และเชลล์ สิ่งที่ต้องกด OK บนรีโมตจะเป็นไปตามการยืนยัน การลงชื่อเข้าใช้ใช้ PIN เดียวกันนี้ หรือบัญชี Google หากเปิดไว้ด้านล่าง แผงควบคุมไม่ได้อยู่บนอินเทอร์เน็ต: มีแค่ MCP",
"Cole a chave inteira (começa com tskey-).":"วางคีย์ทั้งหมด (ขึ้นต้นด้วย tskey-)",
"Cole no arquivo de servidores MCP (mcp.json) e entre com o PIN quando pedir.":"วางลงในไฟล์เซิร์ฟเวอร์ MCP (mcp.json) และลงชื่อเข้าใช้ด้วย PIN เมื่อระบบถาม",
"Com a chave \"Presença\" ligada: se os celulares marcados saírem da rede por 15 min e ninguém mexer no controle, a TV apaga a tela e avisa no celular.":"เมื่อเปิดสวิตช์ \"การอยู่บ้าน\": หากโทรศัพท์ที่เลือกออกจากเครือข่ายนาน 15 นาทีและไม่มีใครแตะรีโมต ทีวีจะปิดหน้าจอและแจ้งไปที่โทรศัพท์ของคุณ",
"Com a chave ligada, um link secreto recebe recados (POST com JSON) do Home Assistant, dos Atalhos do iPhone ou de apps feitos para o TvOverlay. Gerar um link novo invalida o anterior e pede o PIN. O link só aparece agora: guarde-o.":"เมื่อเปิดสวิตช์ ลิงก์ลับจะรับข้อความ (POST พร้อม JSON) จาก Home Assistant, คำสั่งลัดของ iPhone หรือแอปที่สร้างมาสำหรับ TvOverlay การสร้างลิงก์ใหม่จะทำให้ลิงก์เก่าใช้ไม่ได้และต้องใช้ PIN ลิงก์จะแสดงแค่ตอนนี้: บันทึกไว้",
"Com a chave ligada: no horário abaixo, só abrem os apps da lista (os do sistema sempre abrem) e o volume não passa do teto. Salvar pede o PIN.":"เมื่อเปิดสวิตช์: ในช่วงเวลาด้านล่าง จะเปิดได้เฉพาะแอปในรายการ (แอประบบเปิดได้เสมอ) และเสียงจะไม่เกินขีดจำกัด การบันทึกต้องใช้ PIN",
"Com isto, o login do Claude (e dos outros apps) deixa de aceitar o PIN: só passa uma conta Google que esteja em algum perfil desta TV. Crie no Google Cloud um cliente OAuth do tipo \"TVs e dispositivos de entrada limitada\" e cole o id e o segredo aqui. Deixe o id vazio e salve para voltar ao PIN.":"เมื่อเปิด การลงชื่อเข้าใช้ Claude (และแอปอื่น) จะไม่รับ PIN อีก: เข้าได้เฉพาะบัญชี Google ที่อยู่ในโปรไฟล์ใดโปรไฟล์หนึ่งของทีวีนี้ ใน Google Cloud ให้สร้าง OAuth client ประเภท \"TVs and Limited Input devices\" แล้ววาง id และ secret ที่นี่ เว้น id ว่างแล้วบันทึกเพื่อกลับไปใช้ PIN",
"Com o certificado que a TV fez instalado no aparelho, o painel abre com cadeado e vira app no celular e no PC.":"เมื่อติดตั้งใบรับรองของทีวีบนอุปกรณ์แล้ว แผงควบคุมจะเปิดแบบมีแม่กุญแจและกลายเป็นแอปบนโทรศัพท์และคอมพิวเตอร์",
"Com o Fundo do protetor em “Fotos e vídeos passando” (na TV: Configurações › Tela e energia), o protetor mostra estas fotos por trás do relógio. Ficam só na TV, numa pasta do launcher. JPG, PNG ou WebP, até 15 MB cada.":"เมื่อตั้งพื้นหลังโปรแกรมรักษาหน้าจอเป็น “รูปภาพและวิดีโอเลื่อนผ่าน” (บนทีวี: การตั้งค่า › หน้าจอและพลังงาน) โปรแกรมรักษาหน้าจอจะแสดงรูปเหล่านี้หลังนาฬิกา รูปเก็บไว้บนทีวีเท่านั้น ในโฟลเดอร์ของ Launcher JPG, PNG หรือ WebP ไม่เกิน 15 MB ต่อรูป",
