"Esquecer o roteador (apaga endereço, chave e lista)":"ลืมเราเตอร์ (ลบที่อยู่ คีย์ และรายการ)",
"Esquecer o roteador?":"ลืมเราเตอร์ไหม",
"Esquerda":"ซ้าย",
"Esse arquivo não é um backup válido (JSON).":"ไฟล์นี้ไม่ใช่ข้อมูลสำรองที่ถูกต้อง (JSON)",
"Esse é um backup completo: escreva a senha dele no campo abaixo e escolha o arquivo de novo.":"นี่คือข้อมูลสำรองแบบเต็ม: พิมพ์รหัสผ่านในช่องด้านล่างแล้วเลือกไฟล์อีกครั้ง",
"Esta versão do launcher ainda não mostra o acesso remoto.":"Launcher เวอร์ชันนี้ยังไม่แสดงการเข้าถึงระยะไกล",
"Este app não entra em ações em lote (abra Detalhes)":"แอปนี้ไม่ร่วมในการทำงานแบบกลุ่ม (เปิดรายละเอียด)",
"Este app é protegido: o sistema ou o launcher dependem dele. As permissões aparecem só para consulta.":"แอปนี้ได้รับการป้องกัน: ระบบหรือ Launcher ต้องพึ่งพาแอปนี้ สิทธิ์แสดงไว้เพื่ออ้างอิงเท่านั้น",
"Este navegador não recebe avisos por aqui. Abra o painel com cadeado (https, porta 8444) no Chrome do celular: veja Extras, \"Instalar como app\".":"เบราว์เซอร์นี้รับการแจ้งเตือนที่นี่ไม่ได้ เปิดแผงควบคุมแบบมีแม่กุญแจ (https พอร์ต 8444) ใน Chrome บนโทรศัพท์: ดู Extras \"ติดตั้งเป็นแอป\"",
"Ex.: O jantar está pronto!":"เช่น: อาหารเย็นพร้อมแล้ว!",
"Falta a chave de API.":"ไม่มีคีย์ API",
