"Fazer agora":"ทำตอนนี้",
"Fazer o backup toda noite":"สำรองข้อมูลทุกคืน",
"Fecha o app à força (como \"Forçar parada\"). Ele volta ao normal quando for aberto de novo.":"บังคับปิดแอป (เหมือน \"บังคับหยุด\") แอปจะกลับเป็นปกติเมื่อเปิดอีกครั้ง",
"Fecha os apps em segundo plano (o da frente continua). Nada é apagado; o app fechado abre do zero.":"ปิดแอปที่ทำงานเบื้องหลัง (แอปที่อยู่ด้านหน้ายังอยู่) ไม่มีอะไรถูกลบ แอปที่ปิดจะเริ่มใหม่ตั้งแต่ต้น",
"Fechar":"ปิด",
"Feito: a TV sai do Wi-Fi e volta em alguns segundos. Depois, toque em Diagnosticar de novo.":"เสร็จแล้ว: ทีวีจะออกจาก Wi-Fi และกลับมาในไม่กี่วินาที จากนั้นแตะวินิจฉัยอีกครั้ง",
"Fica cifrada na TV. Depois, use \"Testar e recarregar canais\" para ver se ela funciona.":"เก็บแบบเข้ารหัสบนทีวี จากนั้นใช้ \"ทดสอบและโหลดช่องใหม่\" เพื่อดูว่าใช้ได้ไหม",
