"O painel passa a abrir pelos aparelhos da sua conta Tailscale (ainda pede o PIN).":"แผงควบคุมจะเริ่มเปิดได้จากอุปกรณ์ในบัญชี Tailscale ของคุณ (ยังถาม PIN)",
"O primeiro mês aparece amanhã: a TV fecha um dia de cada vez.":"เดือนแรกจะแสดงพรุ่งนี้: ทีวีสรุปทีละวัน",
