"O que dá para pedir":"สิ่งที่คุณขอได้",
"O que ele faz nesta TV agora":"สิ่งที่ทำอยู่บนทีวีนี้ตอนนี้",
"O que mexeu na TV nos últimos 7 dias: painel, Claude, adb e a própria TV. O Claude lê o mesmo diário (ferramenta diario_tv).":"สิ่งที่เปลี่ยนบนทีวีใน 7 วันที่ผ่านมา: แผงควบคุม Claude adb และตัวทีวีเอง Claude อ่านบันทึกเดียวกันนี้ (เครื่องมือ diario_tv)",
"O que o Android avisou":"สิ่งที่ Android รายงาน",
"O roteador usa um certificado próprio. A TV só fala com ele depois de você conferir a impressão digital: abra https://<endereço do roteador> no computador, clique no cadeado e compare com a SHA-256 abaixo.":"เราเตอร์ใช้ใบรับรองของตัวเอง ทีวีจะคุยกับเราเตอร์หลังจากคุณตรวจลายนิ้วมือแล้วเท่านั้น: เปิด https://<router address> บนคอมพิวเตอร์ คลิกแม่กุญแจและเทียบกับ SHA-256 ด้านล่าง",
"O shell do launcher (teclas do painel, comandos do Claude, autocura) e o túnel do Claude pela internet às vezes param sem avisar. Aqui aparece se estão no ar, e o que a TV fez na manutenção da noite.":"เชลล์ของ Launcher (ปุ่มในแผงควบคุม คำสั่งของ Claude การซ่อมตัวเอง) และอุโมงค์อินเทอร์เน็ตของ Claude บางครั้งหยุดโดยไม่แจ้ง ที่นี่คุณดูได้ว่ายังทำงานอยู่ไหม และทีวีทำอะไรในการบำรุงรักษาตอนกลางคืน",
"O shell do launcher não respondeu: sem a lista de memória e sem liberar (a depuração sem fio está ligada?).":"เชลล์ของ Launcher ไม่ตอบ: ไม่มีรายการหน่วยความจำและไม่ได้คืนพื้นที่ (เปิดการแก้ไขข้อบกพร่องแบบไร้สายอยู่ไหม)",
"O vídeo terminou (2 min). Clique em \"Ver ao vivo\" para continuar.":"วิดีโอจบแล้ว (2 นาที) คลิก \"ดูสด\" เพื่อดูต่อ",
