"Só leitura: a TV vê os aparelhos conectados e se o roteador responde. Ela não bloqueia nem muda nada no roteador. A chave fica cifrada na TV e nunca volta para esta página (só os 4 últimos caracteres).":"อ่านอย่างเดียว: ทีวีเห็นอุปกรณ์ที่เชื่อมต่อและดูว่าเราเตอร์ตอบไหม ไม่บล็อกหรือเปลี่ยนอะไรบนเราเตอร์ คีย์เก็บแบบเข้ารหัสบนทีวีและไม่ส่งกลับมาที่หน้านี้ (แค่ 4 ตัวอักษรสุดท้าย)",
