"Toda noite, com a TV parada, ela guarda um backup completo trancado com a senha abaixo (ficam as 7 últimas cópias) e, se quiser, uma cópia extra no pendrive ou numa pasta da rede. Anote a senha: sem ela as cópias não abrem. Trocar a senha ou a cópia extra pede o PIN de novo.":"ทุกคืน เมื่อทีวีว่าง ทีวีจะเก็บข้อมูลสำรองแบบเต็มที่ล็อกด้วยรหัสผ่านด้านล่าง (เก็บ 7 ชุดล่าสุด) และถ้าต้องการ ทำสำเนาเพิ่มบนไดรฟ์ USB หรือโฟลเดอร์เครือข่าย จดรหัสผ่านไว้: ถ้าไม่มีจะเปิดสำเนาไม่ได้ การเปลี่ยนรหัสผ่านหรือสำเนาเพิ่มเติมจะถาม PIN อีกครั้ง",
"Todos os apps →":"แอปทั้งหมด →",
