"Touchpad: arraste para mover, toque para OK":"ทัชแพด: ลากเพื่อเลื่อน แตะเพื่อ OK",
"Travar \"Forçar parada\" e \"Limpar dados\" do launcher e da VPN":"ล็อก \"บังคับหยุด\" และ \"ล้างข้อมูล\" ของ Launcher และ VPN",
"Trocar":"เปลี่ยน",
"Trocar a cópia extra?":"เปลี่ยนสำเนาเพิ่มเติมไหม",
"Trocar foto…":"เปลี่ยนรูป…",
"Trocar o endereço apaga a chave e o certificado guardados (é preciso colar a chave de novo).":"การเปลี่ยนที่อยู่จะลบคีย์และใบรับรองที่บันทึกไว้ (ต้องวางคีย์ใหม่)",
"Tudo o que o backup acima leva e mais: contas de TV ao vivo, chave do UniFi, PIN do painel, controle parental, o Tailscale (a TV volta com o mesmo endereço) e os logins do Claude e dos outros apps no conector. Sai trancado com a senha abaixo: guarde-a, porque sem ela o arquivo não abre. Contas Google, Wi-Fi e logins de outros apps (Netflix, YouTube) o Android não deixa copiar.":"ทุกอย่างที่ข้อมูลสำรองด้านบนมีและมากกว่านั้น: บัญชีทีวีสด คีย์ UniFi PIN ของแผงควบคุม การควบคุมโดยผู้ปกครอง Tailscale (ทีวีกลับมาด้วยที่อยู่เดิม) และการลงชื่อเข้าใช้ของ Claude กับแอปอื่นในตัวเชื่อมต่อ ไฟล์จะล็อกด้วยรหัสผ่านด้านล่าง: เก็บไว้ให้ดี เพราะถ้าไม่มีจะเปิดไฟล์ไม่ได้ Android ไม่อนุญาตให้คัดลอกบัญชี Google, Wi-Fi และการลงชื่อเข้าใช้ของแอปอื่น (Netflix, YouTube)",
"Um app que não está na lista volta do login por um domínio dele (o \"redirect\" que ele mostra, ex.: app.exemplo.com). Libere o domínio aqui, sem esperar versão nova da TV. Pede o PIN, e a TV ainda pergunta \"cliente novo?\" no primeiro login.":"แอปที่ไม่อยู่ในรายการจะกลับมาจากการลงชื่อเข้าใช้ผ่านโดเมนของตัวเอง (\"redirect\" ที่แอปแสดง เช่น app.example.com) อนุญาตโดเมนนั้นที่นี่ โดยไม่ต้องรอทีวีเวอร์ชันใหม่ ต้องใช้ PIN และทีวียังถาม \"ไคลเอนต์ใหม่ไหม\" ในการลงชื่อเข้าใช้ครั้งแรก",
"Uma cena junta várias ações. Cada uma ganha um link secreto para os Atalhos do iPhone ou o Home Assistant (POST). O link só aparece ao criar: guarde-o. Criar e apagar pedem o PIN.":"ฉากรวมการทำงานหลายอย่างไว้ด้วยกัน แต่ละฉากได้ลิงก์ลับสำหรับคำสั่งลัดของ iPhone หรือ Home Assistant (POST) ลิงก์จะแสดงแค่ตอนสร้าง: บันทึกไว้ การสร้างและลบต้องใช้ PIN",
