"Android: um gerenciador de arquivos com WebDAV (Solid Explorer, CX File Explorer, Material Files): porta 8444, caminho /dav/, HTTPS.":"Android: ตัวจัดการไฟล์ที่รองรับ WebDAV (Solid Explorer, CX File Explorer, Material Files): พอร์ต 8444 พาธ /dav/ HTTPS",
"Windows com letra de unidade":"Windows พร้อมอักษรไดรฟ์",
"Só para quem precisa de uma letra (S:, de Sofaly; se estiver ocupada, Y:) para um programa antigo. O conector prepara o Windows (certificado da TV, serviço de unidade de rede e limite de tamanho) e mapeia a unidade: responda \"Sim\" à pergunta do Windows e digite \"tv\" e o PIN.":"สำหรับผู้ที่ต้องการอักษรไดรฟ์ (S: สำหรับ Sofaly หากถูกใช้แล้ว Y:) สำหรับโปรแกรมเก่าเท่านั้น ตัวเชื่อมต่อจะเตรียม Windows (ใบรับรองทีวี บริการไดรฟ์เครือข่าย และขีดจำกัดขนาด) แล้วแมปไดรฟ์: ตอบ \"Yes\" ที่คำถามของ Windows แล้วพิมพ์ \"tv\" และ PIN",
"O espaço livre que o Windows mostra nessa unidade é o do disco do próprio PC, não o da TV: o Windows faz isso com toda unidade desse tipo. O espaço de verdade aparece em Este Computador, no item da TV.":"พื้นที่ว่างที่ Windows แสดงสำหรับไดรฟ์นี้เป็นของดิสก์ PC ไม่ใช่ของทีวี: Windows ทำแบบนี้กับไดรฟ์ประเภทนี้ทุกตัว พื้นที่จริงแสดงใน This PC ที่รายการของทีวี",
