"Virar a câmera":"สลับกล้อง",
"Aponte o celular para a TV, com a tela inteira dentro dos cantos. Segure firme.":"หันโทรศัพท์ไปที่ทีวี ให้ทั้งหน้าจออยู่ในมุมทั้งสี่ ถือให้นิ่ง",
"Terminar":"เสร็จสิ้น",
