"A TV encerrou o microfone.":"ทีวีปิดไมโครโฟนแล้ว",
"A TV não aceitou a conexão. Entre de novo no painel e tente outra vez.":"ทีวีไม่รับการเชื่อมต่อ เข้าสู่แผงควบคุมอีกครั้งแล้วลองใหม่",
"A câmera ofuscou. Afaste um pouco o celular ou diminua a luz da sala e meça de novo.":"กล้องแสงจ้าเกินไป ถอยโทรศัพท์ออกเล็กน้อยหรือหรี่ไฟในห้องแล้ววัดใหม่",
"A medida variou demais (Wi-Fi lento ou barulho na sala). Tente de novo em silêncio.":"ค่าที่วัดแกว่งมากเกินไป (Wi-Fi ช้าหรือห้องมีเสียงดัง) ลองใหม่ตอนเงียบ",
