"Não consegui abrir o microfone. Confira se o navegador tem permissão para usá-lo.":"เปิดไมโครโฟนไม่ได้ ตรวจดูว่าเบราว์เซอร์ได้รับอนุญาตให้ใช้หรือไม่",
"Não ouvi os bipes direito. Suba um pouco o volume da TV, chegue mais perto e tente de novo.":"ได้ยินเสียงบี๊บไม่ชัด เพิ่มเสียงทีวีเล็กน้อย เข้าไปใกล้ขึ้น แล้วลองใหม่",
"O branco puxa para o amarelo. Em Imagem › Temperatura da cor, escolha uma opção mais fria.":"สีขาวอมเหลือง ที่ ภาพ › อุณหภูมิสี ให้เลือกตัวเลือกที่เย็นกว่า",
"O branco puxa para o azul. Em Imagem › Temperatura da cor, escolha uma opção mais quente.":"สีขาวอมฟ้า ที่ ภาพ › อุณหภูมิสี ให้เลือกตัวเลือกที่อุ่นกว่า",
"O branco puxa para o roxo. No Balanço de branco (modo Especialista), suba um pouco o Verde.":"สีขาวอมม่วง ใน สมดุลแสงขาว (โหมดผู้เชี่ยวชาญ) ให้เพิ่มสีเขียวเล็กน้อย",
"O branco puxa para o verde. No Balanço de branco (modo Especialista), desça um pouco o Verde.":"สีขาวอมเขียว ใน สมดุลแสงขาว (โหมดผู้เชี่ยวชาญ) ให้ลดสีเขียวเล็กน้อย",
"O preto está acinzentado. Desça o Brilho da TV 2 pontos e meça de novo.":"สีดำดูเป็นสีเทา ลดความสว่างของทีวีลง 2 ระดับแล้ววัดใหม่",
