"Os pretos mais escuros somem. Suba o Brilho da TV 2 pontos e meça de novo.":"สีดำที่มืดที่สุดหายไป เพิ่มความสว่างของทีวีขึ้น 2 ระดับแล้ววัดใหม่",
"Ouvindo os bipes da TV. Fique em silêncio por 6 segundos, com o celular perto de onde você assiste.":"กำลังฟังเสียงบี๊บจากทีวี เงียบไว้ 6 วินาที โดยวางโทรศัพท์ใกล้ที่ที่คุณนั่งดู",
"Para usar a câmera, abra o painel pelo endereço https (porta 8444). No http o navegador não libera a câmera.":"หากต้องการใช้กล้อง ให้เปิดแผงควบคุมผ่านที่อยู่ https (พอร์ต 8444) ผ่าน http เบราว์เซอร์จะไม่อนุญาตกล้อง",
"Para usar o microfone, abra o painel pelo endereço https (porta 8444). No http o navegador não libera o microfone.":"หากต้องการใช้ไมโครโฟน ให้เปิดแผงควบคุมผ่านที่อยู่ https (พอร์ต 8444) ผ่าน http เบราว์เซอร์จะไม่อนุญาตไมโครโฟน",
